export const M73_REPORT_TEMPLATE=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Synthetic stationary natural-gas source report</title><style>body{font:16px/1.5 system-ui;margin:2rem auto;padding:0 1rem;max-width:900px;color:#172f2c;overflow-wrap:anywhere}h1,h2{line-height:1.2}dt{font-weight:700}dd{margin:0 0 .6rem}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.5 monospace;background:#f3f6f3;padding:1rem}li{margin:.3rem 0}table{border-collapse:collapse;width:100%}th,td{padding:.45rem;text-align:left;border-bottom:1px solid #ccd8d0}@media print{body{font-size:11pt;margin:0;max-width:none}h2{break-after:avoid}pre{font-size:9pt}.technical-appendix:not([open]){display:none}}</style></head><body><h1>Stationary natural-gas source report — synthetic internal draft</h1><p>Development candidate · Not released. Corporate inventory incomplete. No filing determination or external assurance.</p><h2>Source and activity</h2><dl>{{facts}}</dl><h2>Gas results and calculation trace</h2>{{calculation}}<h2>Supporting synthetic statement</h2><dl>{{statement}}</dl><h2>Corporate coverage remains incomplete</h2><p>Stationary combustion is partial. Mobile combustion, fugitive emissions including refrigerants, process emissions, other sources/facilities/periods, Scope 2 and all 15 Scope 3 categories remain unresolved or separately assessed. Combustion only; upstream fuel emissions excluded.</p><ul>{{findings}}</ul><details class="technical-appendix"><summary>Exact version and provenance record</summary><pre>{{snapshot}}</pre></details></body></html>`
import type {M73Version,M73Review} from './m73-contract'
