}
export async function reviewStationaryGas(tx:WorkspaceSql,companyId:string,worksheetId:string,input:M73ReviewInput,authority:M73Authority){await locked(tx,companyId);await readStationaryGas(tx,companyId,authority);const id=(await tx.query<{id:string}>('select neuvetra.review_stationary_gas($1,$2,$3::text::jsonb) id',[companyId,worksheetId,JSON.stringify(validateM73Review(input))])).rows[0]!.id;const after=await readStationaryGas(tx,companyId,authority);return after?.worksheets.flatMap(w=>w.versions).map(v=>v.review).find(r=>r?.id===id)??fail()}
export async function createStationaryGasReport(tx:WorkspaceSql,companyId:string,worksheetId:string,input:M73ReportInput,authority:M73Authority){await locked(tx,companyId);await readStationaryGas(tx,companyId,authority);const id=(await tx.query<{id:string}>('select neuvetra.create_stationary_gas_report($1,$2,$3::text::jsonb) id',[companyId,worksheetId,JSON.stringify(validateM73Report(input))])).rows[0]!.id;const after=await readStationaryGas(tx,companyId,authority);return after?.worksheets.flatMap(w=>w.reports).find(r=>r.id===id)??fail()}

