export * from './m76-diesel-contract'
export * from './m76-diesel-validation'
export * from './m76-diesel-report'
export const m76DieselHash=(v:unknown)=>new Bun.CryptoHasher('sha256').update(m76DieselCanonicalJson(v)).digest('hex')
export const m76DieselBytesHash=(s:string)=>new Bun.CryptoHasher('sha256').update(s).digest('hex')
const bytes=(s:string)=>new TextEncoder().encode(s).length
const same=(a:unknown,b:unknown)=>m76DieselCanonicalJson(a)===m76DieselCanonicalJson(b)
const flags={synthetic:true as const,scope1Completeness:'incomplete' as const,corporateCompleteness:'incomplete' as const,releaseEligible:false as const,assurance:'none' as const}
const fail=():never=>{throw Error('Stored stationary-generator workpaper could not be verified.')}
const verify=(v:unknown)=>{if(!v)fail()}
const iso=(v:string)=>{const d=new Date(v);return Number.isFinite(d.getTime())?d.toISOString():fail()}
type RequestRow={company_id:string;idempotency_key:string;actor_id:string;kind:string;fingerprint:string;record_id:string}
type AuditRow={company_id:string;record_id:string;kind:string;record_sha256:string;actor_id:string;created_at:string}
export async function readStationaryDiesel(tx:WorkspaceSql,companyId:string,authority:M76DieselAuthority):Promise<M76DieselRegister|null>{
 if(!(await tx.query<{allowed:boolean}>('select neuvetra.m76_diesel_lock($1,false) allowed',[companyId])).rows[0]?.allowed)return null
 const coverage=await readCorporateInventory(tx,companyId);if(!coverage)return null
 const data=(await tx.query<{heads:any[];versions:any[];statements:any[];reviews:any[];reports:any[];requests:RequestRow[];audits:AuditRow[];reservations:{company_id:string;worksheet_id:string;kind:string;evidence_key:string}[]}>(`select
 coalesce((select jsonb_agg(x order by id) from neuvetra.stationary_diesel_heads x where company_id=$1),'[]') heads,
 coalesce((select jsonb_agg(to_jsonb(x)||jsonb_build_object('quantity_gallons',x.quantity_gallons::text) order by worksheet_id,version) from neuvetra.stationary_diesel_versions x where company_id=$1),'[]') versions,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_diesel_statements x where company_id=$1),'[]') statements,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_diesel_reviews x where company_id=$1),'[]') reviews,
 coalesce((select jsonb_agg(x order by created_at,id) from neuvetra.stationary_diesel_reports x where company_id=$1),'[]') reports,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_diesel_requests x where company_id=$1),'[]') requests,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_diesel_audit x where company_id=$1),'[]') audits,
 coalesce((select jsonb_agg(x) from neuvetra.stationary_diesel_evidence_reservations x where company_id=$1),'[]') reservations`,[companyId])).rows[0]!
 verify(data.heads.length<=1&&data.versions.length<=40&&data.reports.length<=40&&data.audits.length===data.versions.length+data.reviews.length+data.reports.length&&data.requests.length===data.audits.length)
 const audit=(kind:string,id:string,hash:string,actor:string,time:string,worksheetId:string|null,request:unknown)=>{const rows=data.audits.filter(a=>a.kind===kind&&a.record_id===id),req=data.requests.filter(r=>r.kind===kind&&r.record_id===id);verify(rows.length===1&&req.length===1);const a=rows[0]!,r=req[0]!;verify(a.company_id===companyId&&a.actor_id===actor&&a.record_sha256===hash&&iso(a.created_at)===time&&r.company_id===companyId&&r.actor_id===actor&&m71Uuid(r.idempotency_key)&&r.fingerprint===m76DieselHash({operation:kind,actor,companyId,worksheetId,request}))}
 const all:M76DieselVersion[]=[]
 const worksheets:M76DieselRegister['worksheets']=[]
 for(const head of data.heads){verify(head.company_id===companyId&&m71Uuid(head.id)&&m71Uuid(head.source_id));const versions:M76DieselVersion[]=[]
  for(const row of data.versions.filter(r=>r.worksheet_id===head.id)){
   const v=structuredClone(row.payload) as M76DieselVersion,prior=versions[versions.length-1]
   try{m76DieselKeys(v,['id','companyId','worksheetId','version','previousVersionId','previousVersionSha256','createdBy','createdAt','contributorIds','correctionReason','activity','activityStatus','coverageVersion','statement','calculation','findings','inputSha256','contentSha256','versionSha256','synthetic','scope1Completeness','corporateCompleteness','releaseEligible','assurance','review'])}catch{return fail()}
