export function m76ValidateResolvedReferences(activity:M76Activity,coverage:M71Version):void{for(const row of activity.rosterStatement?.assets??[]){require(row.entityId===null||coverage.snapshot.entities.some(x=>x.id===row.entityId),'Declared entity does not resolve in this corporate version.');require(row.facilityId===null||coverage.snapshot.facilities.some(x=>x.id===row.facilityId),'Declared facility does not resolve in this corporate version.')}for(const link of activity.links)require(link.sourceId===null||coverage.snapshot.sources.some(x=>x.id===link.sourceId),'Mapped source does not resolve in this corporate version.');for(const id of activity.rosterStatement?.coveredEntityIds??[])require(coverage.snapshot.entities.some(x=>x.id===id),'Covered entity does not resolve.');for(const id of activity.rosterStatement?.coveredFacilityIds??[])require(coverage.snapshot.facilities.some(x=>x.id===id),'Covered facility does not resolve.')}
