  if(req.kind==='save'){const v=versions.find(v=>v.id===req.record_id)??fail();actor=v.createdBy;rosterId=v.previousVersionId?v.rosterId:null;request={...v.activity,expectedDependencySha256:v.dependencies.dependencySha256,expectedVersionId:v.previousVersionId,expectedVersionSha256:v.previousVersionSha256,correctionReason:v.correctionReason}}
