 }
 verify(!head&&versions.length===0||head&&head.version_id===last(versions)?.id&&head.revision===versions.length);verify(data.statements.every(s=>versions.some(v=>v.statement?.id===s.id)));const current=last(versions)??null,rawBound=current?coverage.versions.find(v=>v.id===current.activity.coverageVersionId&&v.versionSha256===current.activity.coverageVersionSha256)??fail():null,boundCoverageVersion=rawBound?{...rawBound,review:current?.dependencies.coverageReviewPin?(rawBound.review?.id===current.dependencies.coverageReviewPin.id&&rawBound.review.decisionSha256===current.dependencies.coverageReviewPin.sha256?rawBound.review:fail()):null}:null,reconciliation=deriveM76Reconciliation(companyId,currentCoverage,gasWorkpapers,dieselWorkpapers,current,reviews,m76Hash),result:M76Register={profile:M76_PROFILE,companyId,rosterId:head?.id??null,headVersionId:head?.version_id??null,versions,reviews,reports:reports.map(({snapshotJson:_,html:__,...meta})=>meta),proof:{coverageVersion:currentCoverage,boundCoverageVersion,gasWorkpaperVersions:gasWorkpapers,dieselWorkpaperVersions:dieselWorkpapers},reconciliation,limitations:[...M76_LIMITATIONS]};verify(bytes(m76CanonicalJson(result))<=M76_MAX_RESPONSE_BYTES&&data.versions.reduce((n,x)=>n+bytes(x.export_text),0)+data.reports.reduce((n,x)=>n+bytes(x.payload.html)+bytes(x.payload.snapshotJson),0)<=M76_MAX_HISTORY_BYTES);return result
