export async function readStationaryEquipmentReport(tx:WorkspaceSql,companyId:string,rosterId:string,reportId:string,authority:M76Authorities):Promise<M76Report|null>{const register=await readStationaryEquipment(tx,companyId,authority);if(!register||register.rosterId!==rosterId||!register.reports.some(x=>x.id===reportId))return null;return (await tx.query<ReportRow>('select * from neuvetra.stationary_equipment_reports where company_id=$1 and roster_id=$2 and id=$3',[companyId,rosterId,reportId])).rows[0]?.payload??null}
export async function readStationaryEquipmentReportProof(tx:WorkspaceSql,companyId:string,rosterId:string,reportId:string,authority:M76Authorities):Promise<M76ReportProof|null>{const report=await readStationaryEquipmentReport(tx,companyId,rosterId,reportId,authority);if(!report)return null;const snapshot=JSON.parse(report.snapshotJson) as ReturnType<typeof m76ReportSnapshot>,coverage=await readCorporateInventory(tx,companyId),gas=await readStationaryGas(tx,companyId,authority.gas),diesel=await readStationaryDiesel(tx,companyId,authority.diesel);if(!coverage||!gas||!diesel)return fail();return {reportId,proof:proofForPins(coverage,gas,diesel,snapshot.reconciliation,{id:snapshot.version.activity.coverageVersionId,sha256:snapshot.version.activity.coverageVersionSha256})}}

