export async function reviewStationaryEquipment(tx:WorkspaceSql,actor:string,companyId:string,rosterId:string,inputValue:M76ReviewInput,authority:M76Authorities){const input=validateM76Review(inputValue);await lock(tx,companyId,true);const before=await readStationaryEquipment(tx,companyId,authority),v=before?.versions.find(x=>x.id===input.versionId);if(!before||!v||before.rosterId!==rosterId||v.versionSha256!==input.expectedVersionSha256||before.reconciliation.dependencySha256!==input.expectedDependencySha256)throw Object.assign(Error('Review dependencies changed.'),{code:'23505'});if(v.contributorIds.includes(actor))throw Object.assign(Error('Contributors cannot review.'),{code:'42501'});const blockers=before.reconciliation.findings.filter(x=>x.blocking&&x.code!=='roster_review_required');if(input.decision==='accepted_bounded_reconciliation'&&blockers.length)throw Object.assign(Error('Blocked reconciliation cannot be accepted.'),{code:'22023'});const now=new Date().toISOString(),body={id:crypto.randomUUID(),versionId:v.id,versionSha256:v.versionSha256,dependencies:buildM76Dependencies(before.proof.coverageVersion,before.proof.gasWorkpaperVersions,before.proof.dieselWorkpaperVersions,m76Hash),decision:input.decision,note:input.note,acknowledgedLimitations:input.acknowledgedLimitations,reviewerId:actor,reviewedAt:now},review:M76Review={...body,decisionSha256:m76Hash({profile:M76_PROFILE,companyId,...body})},id=(await tx.query<{id:string}>('select neuvetra.review_stationary_equipment($1,$2,$3::text::jsonb,$4::text::jsonb) id',[companyId,rosterId,JSON.stringify(input),JSON.stringify(review)])).rows[0]!.id,after=await readStationaryEquipment(tx,companyId,authority);return after?.reviews.find(x=>x.id===id)??fail()}

