 insert into neuvetra.controlled_fleet_versions values((version_payload->>'id')::uuid,target_company,head.id,(version_payload->>'version')::integer,nullif(version_payload->>'previousVersionId','')::uuid,(version_payload#>>'{activity,coverageVersionId}')::uuid,statement_id,version_payload,version_payload->>'inputSha256',version_payload->>'contentSha256',version_payload->>'versionSha256',actor,captured,neuvetra.m67_canonical(version_payload));update neuvetra.controlled_fleet_heads set version_id=(version_payload->>'id')::uuid,revision=revision+1 where company_id=target_company;
