import type { WorkspaceSql } from "./workspace"

export const EXISTING_PROJECT_REF = "icockcoguyadhryzydvl"
// Exact provider namespaces only. Unknown and newly created schemas are applications by default.
export const SUPABASE_MANAGED_SCHEMAS = [
  "auth", "storage", "realtime", "extensions", "graphql", "graphql_public", "supabase_functions",
  "supabase_migrations", "vault", "net", "cron", "pgbouncer", "pgsodium", "pgsodium_masks",
] as const
export const REVIEWED_APPLICATION_SCHEMAS = ["public","frontdesk","site","terrascope","neuvetra_research_dev","neuvetra","drizzle"] as const
interface DefaultGrant { schema_name:string|null;owner:string;object_type:string;role:string;privilege:string }
const isContainedProviderDefault = (row:DefaultGrant) => row.owner==="supabase_admin" && row.schema_name==="public" && ["r","f","S"].includes(row.object_type)
interface SchemaInventory { schema_name: string; owner: string }
export interface LegacyExposureAudit {
  legacyContainmentVerified: boolean
  scope: "all-application-schemas"
  applicationSchemas: string[]
  unreviewedApplicationSchemas: string[]
  providerDefaultPolicy: "supabase-admin-public-defaults-behind-denied-schema-v1"
  deferredProviderDefaultGrants: DefaultGrant[]
  blockingDefaultGrants: DefaultGrant[]
  managedSchemas: Array<SchemaInventory & { assessment: "provider-managed-separate-review-required" }>
  endpointRolesPresent: boolean
  databaseCreate: Array<{ role: string; allowed: boolean }>
  schemaUsage: Array<{ schema_name: string; role: string; allowed: boolean; create_allowed: boolean }>
  tableGrants: Array<{ schema_name: string; role: string; table_name: string; privilege: string; rls: boolean }>
  columnGrants: Array<{ schema_name: string; role: string; table_name: string; column_name: string; privilege: string }>
  sequenceGrants: Array<{ schema_name: string; role: string; sequence_name: string; privilege: string }>
  callableFunctions: Array<{ schema_name: string; role: string; signature: string; security_definer: boolean }>
  defaultGrants: DefaultGrant[]
}

/** Catalog only. Effective privileges include PUBLIC and inherited roles; no application rows are read. */
export async function auditLegacyStagingExposure(db: WorkspaceSql): Promise<LegacyExposureAudit> {
  const inventory = await db.query<SchemaInventory>("select nspname schema_name,pg_get_userbyid(nspowner) owner from pg_namespace where nspname !~ '^pg_' and nspname <> 'information_schema' order by nspname")
  const managed = new Set<string>(SUPABASE_MANAGED_SCHEMAS)
  const applicationSchemas = inventory.rows.filter(row => !managed.has(row.schema_name)).map(row => row.schema_name)
  const reviewed = new Set<string>(REVIEWED_APPLICATION_SCHEMAS)
  const unreviewedApplicationSchemas = applicationSchemas.filter(schema => !reviewed.has(schema))
  const managedSchemas = inventory.rows.filter(row => managed.has(row.schema_name)).map(row => ({...row,assessment:"provider-managed-separate-review-required" as const}))
  const roles = await db.query<{ role: string; allowed: boolean }>("select rolname role,has_database_privilege(rolname,current_database(),'CREATE') allowed from pg_roles where rolname in ('anon','authenticated') order by rolname")
  const schemas = await db.query<LegacyExposureAudit["schemaUsage"][number]>(`select n.nspname schema_name,r.rolname role,
    has_schema_privilege(r.oid,n.oid,'USAGE') allowed,has_schema_privilege(r.oid,n.oid,'CREATE') create_allowed
    from pg_namespace n cross join pg_roles r where n.nspname=any($1::text[]) and r.rolname in('anon','authenticated') order by n.nspname,r.rolname`,[applicationSchemas])
  const tables = await db.query<LegacyExposureAudit["tableGrants"][number]>(`select n.nspname schema_name,r.rolname role,c.relname table_name,p.privilege,c.relrowsecurity rls
    from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join pg_roles r
    cross join (select column1 privilege from (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) q union all select 'MAINTAIN' where current_setting('server_version_num')::integer>=170000) p
    where n.nspname=any($1::text[]) and c.relkind in ('r','p','v','m','f') and r.rolname in ('anon','authenticated')
    and has_table_privilege(r.oid,c.oid,p.privilege) order by n.nspname,r.rolname,c.relname,p.privilege`,[applicationSchemas])
  const columns = await db.query<LegacyExposureAudit["columnGrants"][number]>(`select n.nspname schema_name,r.rolname role,c.relname table_name,a.attname column_name,p.privilege
    from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid cross join pg_roles r
    cross join (values('SELECT'),('INSERT'),('UPDATE'),('REFERENCES')) p(privilege)
    where n.nspname=any($1::text[]) and c.relkind in('r','p','v','m','f') and a.attnum>0 and not a.attisdropped and a.attacl is not null
    and r.rolname in('anon','authenticated') and has_column_privilege(r.oid,c.oid,a.attnum,p.privilege)
    order by n.nspname,c.relname,a.attname,r.rolname,p.privilege`,[applicationSchemas])
  const sequences = await db.query<LegacyExposureAudit["sequenceGrants"][number]>(`select n.nspname schema_name,r.rolname role,c.relname sequence_name,p.privilege
    from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join pg_roles r cross join(values('USAGE'),('SELECT'),('UPDATE')) p(privilege)
    where n.nspname=any($1::text[]) and c.relkind='S' and r.rolname in('anon','authenticated') and has_sequence_privilege(r.oid,c.oid,p.privilege)
    order by n.nspname,c.relname,r.rolname,p.privilege`,[applicationSchemas])
  const functions = await db.query<LegacyExposureAudit["callableFunctions"][number]>(`select n.nspname schema_name,r.rolname role,p.oid::regprocedure::text signature,p.prosecdef security_definer
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join pg_roles r
    where n.nspname=any($1::text[]) and r.rolname in ('anon','authenticated') and has_function_privilege(r.oid,p.oid,'EXECUTE') order by n.nspname,role,signature`,[applicationSchemas])
  const defaults = await db.query<LegacyExposureAudit["defaultGrants"][number]>(`select n.nspname schema_name,pg_get_userbyid(d.defaclrole) owner,d.defaclobjtype::text object_type,
    case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end role,a.privilege_type privilege
    from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace cross join lateral aclexplode(d.defaclacl) a
    where (d.defaclnamespace=0 or n.nspname=any($1::text[]))
    and (a.grantee=0 or exists(select 1 from pg_roles r where r.rolname in('anon','authenticated') and pg_has_role(r.oid,a.grantee,'USAGE')))
    order by n.nspname,owner,object_type,role,privilege`,[applicationSchemas])
  const deferredProviderDefaultGrants=defaults.rows.filter(isContainedProviderDefault)
  const blockingDefaultGrants=defaults.rows.filter(row=>!isContainedProviderDefault(row))
  return {
    legacyContainmentVerified: unreviewedApplicationSchemas.length===0 && roles.rows.length===2 && roles.rows.every(r=>!r.allowed) && schemas.rows.every(r=>!r.allowed&&!r.create_allowed)
      && tables.rows.length===0 && columns.rows.length===0 && sequences.rows.length===0 && functions.rows.length===0 && blockingDefaultGrants.length===0,
    scope:"all-application-schemas",applicationSchemas,unreviewedApplicationSchemas,managedSchemas,
    providerDefaultPolicy:"supabase-admin-public-defaults-behind-denied-schema-v1",deferredProviderDefaultGrants,blockingDefaultGrants,endpointRolesPresent:roles.rows.length===2,
    databaseCreate:roles.rows,schemaUsage:schemas.rows,tableGrants:tables.rows,columnGrants:columns.rows,sequenceGrants:sequences.rows,
    callableFunctions:functions.rows,defaultGrants:defaults.rows,
  }
}

/** Reviewable application containment only. Never modifies provider-managed schemas automatically. */
export async function planLegacyStagingContainment(db: WorkspaceSql): Promise<{ audit: LegacyExposureAudit; statements: string[]; globalDefaultPrivilegeOwners: string[]; providerAdminStatements: string[]; deferredProviderDefaultGrants: DefaultGrant[] }> {
  const audit = await auditLegacyStagingExposure(db)
  const quote = (value: string) => `"${value.replaceAll('"','""')}"`
  const current = await db.query<{ name:string }>("select current_database() name")
  if (!current.rows[0]) throw new Error("Database catalog unavailable.")
  const kind:Record<string,string>={r:"TABLES",S:"SEQUENCES",f:"FUNCTIONS",T:"TYPES",n:"SCHEMAS"}
  const statements=[`REVOKE CREATE ON DATABASE ${quote(current.rows[0].name)} FROM PUBLIC, anon, authenticated;`]
  for(const schema of audit.applicationSchemas){
    statements.push(`REVOKE ALL ON SCHEMA ${quote(schema)} FROM PUBLIC, anon, authenticated;`,
      `REVOKE ALL ON ALL TABLES IN SCHEMA ${quote(schema)} FROM PUBLIC, anon, authenticated;`,
      `REVOKE ALL ON ALL SEQUENCES IN SCHEMA ${quote(schema)} FROM PUBLIC, anon, authenticated;`,
      `REVOKE ALL ON ALL FUNCTIONS IN SCHEMA ${quote(schema)} FROM PUBLIC, anon, authenticated;`)
  }
  // Table-level REVOKE does not clear column-level grants. Include every observed column privilege.
  for(const row of audit.columnGrants) statements.push(`REVOKE ${row.privilege} (${quote(row.column_name)}) ON TABLE ${quote(row.schema_name)}.${quote(row.table_name)} FROM PUBLIC, anon, authenticated;`)
  const providerAdminStatements:string[]=[]
  for(const row of audit.defaultGrants){
    if(!kind[row.object_type]) throw new Error("Unknown default privilege object type requires review.")
    const target=isContainedProviderDefault(row)?providerAdminStatements:statements
    target.push(`ALTER DEFAULT PRIVILEGES FOR ROLE ${quote(row.owner)}${row.schema_name?` IN SCHEMA ${quote(row.schema_name)}`:""} REVOKE ALL ON ${kind[row.object_type]} FROM PUBLIC, anon, authenticated;`)
  }
  return {audit,statements:[...new Set(statements)],providerAdminStatements:[...new Set(providerAdminStatements)],deferredProviderDefaultGrants:audit.deferredProviderDefaultGrants,globalDefaultPrivilegeOwners:[...new Set(audit.defaultGrants.filter(row=>row.schema_name===null).map(row=>row.owner))].sort()}
}

import type { WorkspaceConnection, WorkspaceSql } from "./workspace"
import { auditLegacyStagingExposure, EXISTING_PROJECT_REF } from "./staging-audit"

export const STAGING_MIGRATIONS = [
  "0001_company_workspace.sql", "0002_synthetic_bill_intake.sql", "0003_synthetic_bill_calculation.sql",
  "0004_inventory_review.sql", "0005_annual_electricity_register.sql", "0006_inventory_evidence_pack.sql",
  "0007_inventory_draft_report.sql", "0008_inventory_draft_report_review.sql", "0009_private_staging.sql", "0010_manual_electricity_worksheet.sql", "0011_worksheet_reports.sql", "0012_source_electricity_worksheet.sql", "0013_annual_electricity_worksheet.sql", "0014_annual_electricity_evidence.sql",
  "0015_corporate_coverage.sql",
  "0016_stationary_natural_gas.sql",
  "0017_mobile_diesel.sql",
  "0018_controlled_fleet.sql",
  "0019_stationary_sources.sql",
  "0020_fugitive_sources.sql",
  "0021_scope1_inventory.sql",
] as const

export async function readMigrationManifest() {
  return Promise.all(STAGING_MIGRATIONS.map(async name => {
    const sql = await Bun.file(new URL(`./migrations/${name}`, import.meta.url)).text()
    // Normalize checkout newline differences, preserving every SQL token.
    const canonical = sql.replace(/\r\n/g, "\n")
    return { name, sha256: new Bun.CryptoHasher("sha256").update(canonical).digest("hex"), sql: canonical }
  }))
}

async function validateExisting(tx: WorkspaceSql, expectedProjectRef: string, manifest: Awaited<ReturnType<typeof readMigrationManifest>>) {
  const receipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra.schema_migrations order by name")
  const target = await tx.query<{ project_ref: string; profile: string }>("select project_ref,profile from neuvetra.staging_target")
  if (target.rows.length !== 1 || target.rows[0]?.project_ref !== expectedProjectRef || target.rows[0]?.profile !== "neuvetra.private-synthetic-staging.v1" || receipts.rows.length !== manifest.length || receipts.rows.some((r, i) => r.name !== manifest[i]?.name || r.sha256 !== manifest[i]?.sha256)) throw new Error("Unknown or changed staging migration baseline.")
}

/** Explicit operator call. Requires a reviewed synthetic target; never called by HTTP startup. */
export async function migratePrivateStaging(db: WorkspaceConnection, approval: { expectedProjectRef: string; syntheticTargetConfirmed: true; reuseExistingProject?: boolean }) {
  if (approval.syntheticTargetConfirmed !== true || !/^[a-z]{20}$/.test(approval.expectedProjectRef)) throw new Error("Reviewed synthetic staging target required.")
  if (approval.expectedProjectRef === EXISTING_PROJECT_REF && (approval.reuseExistingProject !== true || !(await auditLegacyStagingExposure(db)).legacyContainmentVerified)) throw new Error("Confirmed existing project reuse and verified legacy containment required.")
  const manifest = await readMigrationManifest()
  await db.transaction(async tx => {
    await tx.query("select pg_advisory_xact_lock(630009)")
    const existing = await tx.query<{ present: boolean }>("select exists(select 1 from pg_namespace where nspname='neuvetra') present")
    if (existing.rows[0]?.present) {
      const receipts = await tx.query<{ name: string; sha256: string }>("select name,sha256 from neuvetra.schema_migrations order by name")
      if (receipts.rows.length !== 9 && receipts.rows.length !== 10 && receipts.rows.length !== 11 && receipts.rows.length !== 12 && receipts.rows.length !== 13 && receipts.rows.length !== 14 && receipts.rows.length !== 15 && receipts.rows.length !== 16 && receipts.rows.length !== 17 && receipts.rows.length !== 18 && receipts.rows.length !== 19 && receipts.rows.length !== 20 && receipts.rows.length !== manifest.length) throw new Error("Unknown staging migration baseline.")
      await validateExisting(tx, approval.expectedProjectRef, manifest.slice(0,receipts.rows.length))
      for (const migration of manifest.slice(receipts.rows.length)) {
        await tx.exec(migration.sql)
        await tx.query("insert into neuvetra.schema_migrations(name,sha256) values($1,$2)",[migration.name,migration.sha256])
      }
      return
    }
    // Supabase must provide real Auth; no fake users, auth function or role creation here.
    await tx.query("select auth.uid()")
    const auth = await tx.query<{ present: boolean }>("select to_regclass('auth.users') is not null and exists(select 1 from pg_roles where rolname='authenticated') present")
    if (!auth.rows[0]?.present) throw new Error("Real Auth baseline required.")
    for (const migration of manifest) await tx.exec(migration.sql)
    await tx.exec(`create table neuvetra.schema_migrations(name text primary key,sha256 text not null check(sha256 ~ '^[0-9a-f]{64}$'),applied_at timestamptz not null default now());
      create table neuvetra.staging_target(singleton boolean primary key default true check(singleton),project_ref text not null,profile text not null);
      alter table neuvetra.schema_migrations enable row level security; alter table neuvetra.schema_migrations force row level security;
      alter table neuvetra.staging_target enable row level security; alter table neuvetra.staging_target force row level security;
      create policy m63_receipts_read on neuvetra.schema_migrations for select to neuvetra_runtime using(true);
      create policy m63_target_read on neuvetra.staging_target for select to neuvetra_runtime using(true);
      grant select on neuvetra.schema_migrations,neuvetra.staging_target to neuvetra_runtime;`)
    for (const migration of manifest) await tx.query("insert into neuvetra.schema_migrations(name,sha256) values($1,$2)", [migration.name, migration.sha256])
    await tx.query("insert into neuvetra.staging_target(project_ref,profile) values($1,'neuvetra.private-synthetic-staging.v1')", [approval.expectedProjectRef])
  })
  return { schemaVersion: manifest.length, migrations: manifest.map(({ name, sha256 }) => ({ name, sha256 })) }
}

export interface ApprovedStagingRoster {
  expectedProjectRef: string
  workspaceId: string
  ownerUserId: string
  members: ReadonlyArray<{ userId: string; role: "admin" | "member" }>
}

/** Trusted operator-only provisioning of explicitly approved existing real Auth UUIDs. */
export async function provisionStagingRoster(db: WorkspaceConnection, roster: ApprovedStagingRoster): Promise<{ workspaceId: string }> {
  const ids = [roster.ownerUserId, ...roster.members.map(m => m.userId)]
  const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
  if (!uuid.test(roster.workspaceId) || ids.some(id => !uuid.test(id)) || new Set(ids).size !== ids.length || roster.members.some(m => !["admin", "member"].includes(m.role))) throw new Error("Explicit distinct approved Auth subjects required.")
  const manifest = await readMigrationManifest()
  await db.transaction(async tx => {
    await tx.query("select pg_advisory_xact_lock(630009)")
    await validateExisting(tx, roster.expectedProjectRef, manifest)
    for (const id of ids) {
      const subject = await tx.query<{ id: string }>("select id from auth.users where id=$1", [id])
      if (subject.rows.length !== 1) throw new Error("Approved subject does not exist in target Auth.")
      const previous = await tx.query<{ company_id: string | null }>("select company_id from neuvetra.staging_access where user_id=$1", [id])
      if (previous.rows.length && previous.rows[0]?.company_id !== roster.workspaceId) throw new Error("Subject already belongs to another staging roster.")
    }
    const existing = await tx.query<{ created_by: string }>("select created_by from neuvetra.companies where id=$1", [roster.workspaceId])
    if (existing.rows.length && existing.rows[0]?.created_by !== roster.ownerUserId) throw new Error("Staging workspace owner mismatch.")
    if (!existing.rows.length) {
      await tx.query("insert into neuvetra.staging_access(user_id,active) values($1,true)", [roster.ownerUserId])
      await tx.query("select set_config('request.jwt.claim.sub',$1,true)", [roster.ownerUserId])
      await tx.query("select neuvetra.create_company_workspace($1,'Synthetic Acme, Inc.',$2,'Synthetic California office',$3,2023,$4)", [roster.workspaceId, crypto.randomUUID(), crypto.randomUUID(), crypto.randomUUID()])
    }
    // Exact replacement revokes absent users for this workspace; no stale JWT override.
    await tx.query("update neuvetra.staging_access set active=false where company_id=$1", [roster.workspaceId])
    for (const member of [{ userId: roster.ownerUserId, role: "owner" }, ...roster.members]) {
      await tx.query("insert into neuvetra.company_members(company_id,user_id,role) values($1,$2,$3) on conflict(company_id,user_id) do update set role=excluded.role", [roster.workspaceId, member.userId, member.role])
      await tx.query("insert into neuvetra.staging_access(user_id,company_id,active) values($1,$2,true) on conflict(user_id) do update set company_id=excluded.company_id,active=true,approved_at=now()", [member.userId, roster.workspaceId])
    }
  })
  return { workspaceId: roster.workspaceId }
}

/** Explicit revocation is independent of Auth JWT lifetime and preserves domain history. */
export async function revokeStagingAccess(db: WorkspaceConnection, userId: string): Promise<void> {
  await db.query("update neuvetra.staging_access set active=false where user_id=$1", [userId])
}

import { X509Certificate } from "node:crypto"

const MAX_CA_BYTES = 65_536
/** A bounded certificate bundle only; never accepts keys, TLS options, or verification overrides. */
export function validateDatabaseCaPem(value: string): string {
  if (!value || Buffer.byteLength(value,"utf8") > MAX_CA_BYTES) throw new Error("Invalid staging database CA bundle.")
  const certificates = value.match(/-----BEGIN CERTIFICATE-----\s+[A-Za-z0-9+/=\r\n]+-----END CERTIFICATE-----/g)
  if (!certificates?.length || certificates.length>10 || value.replace(/-----BEGIN CERTIFICATE-----\s+[A-Za-z0-9+/=\r\n]+-----END CERTIFICATE-----/g,"").trim()) throw new Error("Invalid staging database CA bundle.")
  try {
    for(const certificate of certificates) if(!new X509Certificate(certificate).ca) throw new Error("CA certificate required.")
  } catch { throw new Error("Invalid staging database CA bundle.") }
  return certificates.join("\n")+"\n"
}

/** Operator/runtime explicitly select either a public CA file or a PEM setting. No automatic env loading. */
export async function loadStagingDatabaseCa(options: {caPem?:string;caFile?:string}): Promise<string|undefined> {
  if(options.caPem!==undefined && options.caFile!==undefined) throw new Error("Select one staging database CA source.")
  if(options.caPem!==undefined) return validateDatabaseCaPem(options.caPem)
  if(options.caFile!==undefined){
    if(!options.caFile || options.caFile.length>4096) throw new Error("Invalid staging database CA file.")
    try {
      const file=Bun.file(options.caFile)
      if(file.size>MAX_CA_BYTES) throw new Error("CA bundle exceeds bound.")
      return validateDatabaseCaPem(await file.text())
    } catch { throw new Error("Invalid staging database CA file.") }
  }
  return undefined
}

